MATCH (p:PlantItem {tag: 'P-4101'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
  AND NOT EXISTS {
    MATCH (p)-[:line_to*1..]->(u:Valve)
    WHERE u <> v AND EXISTS { (u)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

